#!/usr/bin/env bash
# Evidence: the governance lock's repo scope is matched on IDENTITY, in BOTH phases.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so
# `generated-by` is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/lock-repo-scope-2026-10-22.sh
#
# captured-at: the revision the working tree sat on when this ran. The COMMITTED copy is
# always one commit AHEAD of that revision (writing this file changes the tree), so no
# `tip:` line is printed — that would be a claim about the range the file cannot make
# about itself.
#
# READ-ONLY: the probe imports the enforcer and repoints its GOVERNANCE_STATE_DIR at a
# throwaway directory, so it cannot read or write live governance state.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
DEPLOYED="${DEPLOYED:-$HOME/.hermes/plugins/governance-enforcer/__init__.py}"
OUT="${OUT:-$REPO/docs/evidence/lock-repo-scope-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() { sed -e "s|$HOME|~|g"; }
say()  { printf '%s\n' "$*"; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "governance lock repo scope — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/lock-repo-scope-2026-10-22.sh (this file wrote itself)"
say "deployed    : ~/.hermes/plugins/governance-enforcer/__init__.py — the copy in force AT"
say "              CAPTURE TIME, i.e. the PRE-DEPLOY (pre-fix) copy. That is what makes the"
say "              differential probe below discriminating; re-running this script AFTER the"
say "              deploy compares the fix with itself and correctly reports no change."
rule

say ""
say "1. The defect, measured on this host"
say "   begin_change recorded a lock with repo_slug=hermes-agent while the session was"
say "   working in hermes-cortex. The write was AUTHORISED anyway, because Phase 1 asked"
say "   only 'does the lock name ANY repo' (_lock_names_a_repo) instead of 'does it name"
say "   THIS one'. The 2026-10-14 fix closed only the names-NO-repo case. Phase 2 in the"
say "   SAME function already applied the correct rule; Phase 1 never called it."
rule

say ""
say "2. The both-ways tests (tests/test_repo_less_lock_handling.py)"
say "   \$ ~/.hermes-cortex/venv/bin/python3 -m pytest tests/test_repo_less_lock_handling.py -q"
~/.hermes-cortex/venv/bin/python3 -m pytest "$REPO/tests/test_repo_less_lock_handling.py" -q 2>&1 | norm | tail -4
say "   rc captured unpiped below"
~/.hermes-cortex/venv/bin/python3 -m pytest "$REPO/tests/test_repo_less_lock_handling.py" -q >/dev/null 2>&1
say "   rc=$?   (0 = all pass, including the foreign-repo case that failed before the fix)"
rule

say ""
say "3. DIFFERENTIAL PROBE (enforcement-change-safety Rule 23)"
say "   The DEPLOYED copy is the oracle: it is the behaviour currently in force. Both copies"
say "   are loaded in ONE process and driven with the same fixtures against a throwaway"
say "   state dir. A verdict that CHANGES is a real behaviour change; the valid cases must"
say "   NOT change."
say ""
~/.hermes-cortex/venv/bin/python3 - "$DEPLOYED" "$REPO/plugins/governance-enforcer/__init__.py" <<'PROBE' 2>&1 | norm
import importlib.util, json, subprocess, sys, tempfile
from datetime import datetime, timezone
from pathlib import Path

DEPLOYED, REPOCOPY = sys.argv[1], sys.argv[2]


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def git_repo(parent, name):
    repo = parent / name
    repo.mkdir()
    subprocess.run(["git", "init", "-q", str(repo)], check=True, capture_output=True)
    return repo


tmp = Path(tempfile.mkdtemp(prefix="lock-scope-probe."))
target = git_repo(tmp, "the-repo-being-written")
other = git_repo(tmp, "a-different-repo")
state = tmp / "state"
state.mkdir()
hb = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()

# (label, lock's repo_path/slug, target_repo passed to the gate, expect_the_verdict_to_change)
CASES = [
    ("lock names THIS repo",            {"repo_path": str(target), "repo_slug": target.name}, str(target), False),
    ("lock names NO repo",              {},                                                    str(target), False),
    ("lock names a DIFFERENT repo",     {"repo_path": str(other), "repo_slug": other.name},    str(target), True),
]

print(f"  {'fixture':34} {'deployed':>9} {'repo copy':>10}   verdict")
print(f"  {'-'*34} {'-'*9} {'-'*10}   -------")
changed_ok = True
for label, repo_fields, target_arg, expect_change in CASES:
    lock = state / ".governance-sess-probe.json"
    lock.write_text(json.dumps({"task_id": "real-work", "session_id": "sess-probe",
                                "heartbeat_at": hb, "ttl_seconds": 3600, **repo_fields}))
    got = {}
    for name, path in (("deployed", DEPLOYED), ("repo", REPOCOPY)):
        mod = load(f"probe_{name}", path)
        mod.GOVERNANCE_STATE_DIR = state
        got[name] = mod._has_governance_lock("sess-probe", target_arg)
    did_change = got["deployed"] != got["repo"]
    verdict = "CHANGED (the fix)" if did_change else "identical"
    print(f"  {label:34} {str(got['deployed']):>9} {str(got['repo']):>10}   {verdict}")
    if did_change != expect_change:
        changed_ok = False

print()
if changed_ok:
    print("  OK: the verdict changed ONLY where the defect was, and the valid cases are")
    print("      byte-for-byte identical in behaviour — the fix is scoped to the hole.")
else:
    print("  FAIL: the changed/unchanged pattern does not match the defect — inspect above.")
sys.exit(0 if changed_ok else 1)
PROBE
probe_rc=${PIPESTATUS[0]}
say "   rc=$probe_rc   (0 = the verdict changed exactly where the defect was)"
rule

say ""
say "4. Syntax + the A4 adversarial gate on the changed file"
bash -n "$REPO/ops/scripts/pre-commit-score" >/dev/null 2>&1
say "   ops/scripts/pre-commit-score syntax_rc=$?  (unchanged by this range; checked for context)"
python3 -m py_compile "$REPO/plugins/governance-enforcer/__init__.py" 2>&1 | norm
say "   plugins/governance-enforcer/__init__.py py_compile_rc=$?"
python3 "$HOME/.hermes-cortex/scripts/adversarial-verify.py" \
    --file "$REPO/plugins/governance-enforcer/__init__.py" --level A4 --gate >/dev/null 2>&1
say "   plugins/governance-enforcer/__init__.py A4_rc=$?"
rule

say ""
say "5. What the fix does, and what it deliberately does NOT do"
say "   • Phase 1 now applies the SAME rule as Phase 2, through ONE shared helper"
say "     (_lock_covers_target), so the two cannot disagree again."
say "   • A lock naming a DIFFERENT repo is REFUSED here, and left LIVE — it is a valid"
say "     lock for its own repo, and deleting it would wreck that session's scope."
say "   • A lock naming NO repo is still released (unchanged 2026-10-14): it can never be"
say "     closed by end_change, so leaving it is a dead end."
say "   • NOT fixed here, and reported: the lock's repo is resolved from an ambient"
say "     per-session hint file (state/session-repo/<session_id>), whose drift produced the"
say "     mis-scope in the first place. With this change that drift is REFUSED loudly"
say "     instead of silently authorising a write in the wrong repository."
rule

say ""
say "6. What this capture covers"
say "   These files are UNCOMMITTED at capture time — the committed copy of this transcript"
say "   lands one commit AFTER the run, so naming a commit here would be a claim the file"
say "   cannot make about itself. HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- plugins/governance-enforcer/__init__.py tests/test_repo_less_lock_handling.py docs/evidence/lock-repo-scope-2026-10-22.sh docs/evidence/lock-repo-scope-2026-10-22.txt | norm | sed 's/^/     /')
rule
say ""
say "end of evidence"
